//! 🎟️ An original typed owner customizes closure while forwarding the actual captured contract.
#![allow(async_fn_in_trait)]
use semio_framework_dispatch_macros::{dyn_enum,dyn_enum_close};
#[dyn_enum(delegate)]
pub trait Counter:Send+'static{fn borrowed(&self)->&u32;fn bump(&mut self,by:u32);async fn total(&self)->u32;fn close(&mut self,releases:usize)->bool;fn closed(&self)->bool;}
pub struct Plain{value:u32,closed:bool}
impl Counter for Plain{fn borrowed(&self)->&u32{&self.value}fn bump(&mut self,by:u32){self.value+=by;}async fn total(&self)->u32{self.value}fn close(&mut self,_:usize)->bool{self.closed=true;true}fn closed(&self)->bool{self.closed}}
pub struct Original{owner:Option<Box<Plain>>}
impl CounterDelegate for Original{type Target=Plain;fn delegate_ref(&self)->&Plain{self.owner.as_deref().unwrap()}fn delegate_mut(&mut self)->&mut Plain{self.owner.as_deref_mut().unwrap()}fn close(&mut self,releases:usize)->bool{let Some(owner)=self.owner.as_mut()else{return true};if !Counter::closed(owner.as_ref()){Counter::close(owner.as_mut(),releases);return false}if releases<std::mem::size_of::<Plain>(){return false}self.owner.take();true}fn closed(&self)->bool{self.owner.is_none()}}
dyn_enum_close!{pub enum Counters:Counter{Direct(Plain),Original(Original)}}
fn ready<F:std::future::Future>(future:F)->F::Output{struct Noop;impl std::task::Wake for Noop{fn wake(self:std::sync::Arc<Self>){}}let waker=std::task::Waker::from(std::sync::Arc::new(Noop));let mut cx=std::task::Context::from_waker(&waker);let mut future=std::pin::pin!(future);match future.as_mut().poll(&mut cx){std::task::Poll::Ready(value)=>value,_=>panic!("fixture future unexpectedly suspended")}}
#[test]fn typed_original_delegate_preserves_actual_calls_and_overrides_terminal_ownership(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let plain=Plain{value:law["initial"].as_u64().unwrap()as u32,closed:false};let original=Box::new(plain);let pointer=&original.value as*const u32;let mut owner=Counters::Original(Original{owner:Some(original)});assert_eq!(Counter::borrowed(&owner)as*const u32,pointer);Counter::bump(&mut owner,law["delta"].as_u64().unwrap()as u32);assert_eq!(ready(Counter::total(&owner)),law["total"].as_u64().unwrap()as u32);for expected in law["closeWithReleaseDenied"].as_array().unwrap(){assert_eq!(Counter::close(&mut owner,0),expected.as_bool().unwrap());assert!(!Counter::closed(&owner));}assert_eq!(Counter::close(&mut owner,std::mem::size_of::<Plain>()),law["closeWithReleaseAdmitted"].as_bool().unwrap());assert!(Counter::closed(&owner));assert!(Counter::close(&mut owner,0));}
